inline constexpr char kLoginBody[] = R"UI(<div class="auth-shell"><section class="auth-story">{{BRAND}}<div class="signal-art" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div><div class="eyebrow"><span data-i18n>Local service portal</span></div><h1><span data-i18n>Clear power data.</span><br><em><span data-i18n>One trusted bridge.</span></em></h1><p><span data-i18n>Monitor Orion XS charger telemetry and send it to your NMEA 2000 network. Configuration stays on this device.</span></p><span class="pill"><span data-i18n>Service Wi-Fi active</span></span></section><section class="card auth-card"><div class="icon-bubble"><svg class="icon"><use href="#i-lock"/></svg></div><div class="eyebrow" style="margin-top:24px"><span data-i18n>Administrator access</span></div><h2><span data-i18n>Welcome back</span></h2><p><span data-i18n>Sign in to view live data and manage the bridge.</span></p><form method="post" action="/login"><label class="field"><span data-i18n>Username</span><input name="user" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" required autofocus></label><label class="field"><span data-i18n>Password</span><input name="password" type="password" autocomplete="current-password" required></label><button class="button primary" id="login-submit" type="submit"><svg class="icon"><use href="#i-arrow"/></svg> <span data-i18n>Sign in</span></button></form><p class="auth-links"><a href="/recover"><span data-i18n>Forgot password?</span></a></p><div class="notice blue"><span data-i18n>Password verification can take a few seconds. Keep this page open after submitting.</span></div><div class="auth-foot"><span data-i18n>Connected locally to the dongle. If the service Wi-Fi is missing, hold BOOT on the device for two seconds.</span></div></section></div><script>(()=>{
const form=document.querySelector('form'),button=document.getElementById('login-submit'),idleContent=button.innerHTML;
form.addEventListener('submit',event=>{
  if(form.dataset.submitting){event.preventDefault();return}
  form.dataset.submitting='1';bridgeI18n.busy(button,'Checking credentials…');
});
// Back/forward restoration can preserve the submitted form and disabled button.
// Restore the idle UI without replaying credentials or creating a request.
window.addEventListener('pageshow',()=>{
  delete form.dataset.submitting;delete button.dataset.busyKey;
  button.disabled=false;button.innerHTML=idleContent;bridgeI18n.apply();
});
})();</script>)UI";

inline constexpr char kRecoveryBody[] = R"UI(<div class="auth-shell"><section class="auth-story">{{BRAND}}<div class="eyebrow" style="margin-top:55px"><span data-i18n>Administrator access</span></div><h1><span data-i18n>Recover access.</span></h1><p><span data-i18n>Reset only the administrator password with physical access to the bridge.</span></p><div class="notice blue"><span data-i18n>Your username, Wi-Fi password, Orion connection, battery names, NMEA assignments and saved data stay unchanged.</span></div></section><section class="card auth-card"><div class="icon-bubble"><svg class="icon"><use href="#i-lock"/></svg></div><h2><span data-i18n>Reset password</span></h2><ol class="recovery-steps"><li><span data-i18n>Find the recovery password in the saved user manual or docs/erstverbindung.md from the project README.</span></li><li><span data-i18n>Keep the physical BOOT button pressed while selecting Reset password below.</span></li><li><span data-i18n>Sign in with your existing username and the documented recovery password. Then choose a new personal password in Settings.</span></li></ol><div class="notice"><span data-i18n>The recovery password is public. Change it immediately after signing in.</span></div><form id="recovery-form" method="post" action="/recover"><input type="hidden" name="csrf" value="{{RECOVERY_CSRF}}"><label class="confirmation"><input type="checkbox" name="confirm_reset" value="yes" required><span data-i18n>I want to reset only the administrator password.</span></label><button class="button primary" id="recovery-submit" type="submit"><svg class="icon"><use href="#i-lock"/></svg><span data-i18n>Reset password</span></button></form><p class="auth-links"><a href="/"><span data-i18n>Back to sign in</span></a></p><div class="auth-foot"><span data-i18n>The reset can take a few seconds. Keep BOOT pressed until the result appears and leave this page open.</span></div></section></div><script>document.getElementById('recovery-form').addEventListener('submit',function(event){if(this.dataset.submitting){event.preventDefault();return}this.dataset.submitting='1';bridgeI18n.busy(document.getElementById('recovery-submit'),'Resetting password…');});</script>)UI";

inline constexpr char kAccountMessageBody[] = R"UI(<div class="auth-shell"><section class="auth-story">{{BRAND}}<div class="eyebrow" style="margin-top:55px"><span data-i18n>Administrator access</span></div><h1><span data-i18n>{{MESSAGE_TITLE}}</span></h1><p><span data-i18n>{{MESSAGE_TEXT}}</span></p></section><section class="card auth-card"><div class="icon-bubble"><svg class="icon"><use href="#i-check"/></svg></div><h2><span data-i18n>Continue to sign in</span></h2><p><span data-i18n>Use your existing username and your updated password.</span></p><a class="button primary" href="/"><span data-i18n>Sign in</span><svg class="icon"><use href="#i-arrow"/></svg></a></section></div>)UI";

inline constexpr char kFirstSetupBody[] = R"UI(<div class="auth-shell"><section class="auth-story">{{BRAND}}<div class="signal-art" aria-hidden="true"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div><div class="eyebrow"><span data-i18n>First installation · Step 1 of 4</span></div><h1><span data-i18n>Let's set up</span><br><em><span data-i18n>your bridge.</span></em></h1><p><span data-i18n>Start with a local administrator account. The guided setup will then show where to find Orion Bluetooth information and how to map it to Garmin.</span></p><span class="pill"><span data-i18n>Your data stays on the dongle</span></span></section><section class="card auth-card"><div class="icon-bubble"><svg class="icon"><use href="#i-lock"/></svg></div><div class="eyebrow" style="margin-top:24px"><span data-i18n>Protect local access</span></div><h2><span data-i18n>Create administrator</span></h2><p><span data-i18n>This account secures the dongle's web interface. It is separate from your Orion Bluetooth PIN.</span></p><form method="post" action="/setup"><label class="field"><span data-i18n>Username</span><input name="user" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" minlength="3" maxlength="32" pattern="(?:[A-Za-z0-9_]|-){3,32}" required autofocus><span class="field-help"><span data-i18n>3–32 letters, numbers, underscores or hyphens.</span></span></label><label class="field"><span data-i18n>Password</span><input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><span class="field-help"><span data-i18n>At least 12 characters. Keep it somewhere safe.</span></span></label><div class="notice" style="margin-bottom:18px"><span data-i18n>Hold the physical BOOT button on the C3 while you select Create administrator.</span></div><button class="button primary" id="setup-submit" type="submit"><svg class="icon"><use href="#i-arrow"/></svg> <span data-i18n>Create administrator</span></button></form><div class="auth-foot"><span data-i18n>Next: use VictronConnect on your phone to find the Orion XS MAC address and Instant Readout encryption key.</span></div></section></div><script>document.querySelector('form').addEventListener('submit',function(){let b=document.getElementById('setup-submit');bridgeI18n.busy(b,'Creating account…');});</script>)UI";

inline constexpr char kRestartBody[] = R"UI(<div class="auth-shell"><section class="auth-story">{{BRAND}}<div class="eyebrow" style="margin-top:55px"><span data-i18n>Configuration updated</span></div><h1><span data-i18n>Bridge</span><br><em><span data-i18n>restarting.</span></em></h1><p><span data-i18n>Your change was saved on the dongle. The service page will be available again after it starts.</span></p></section><section class="card auth-card"><div class="icon-bubble"><svg class="icon"><use href="#i-refresh"/></svg></div><h2><span data-i18n>One moment</span></h2><p><span data-i18n>Keep your phone on the OrionBridge Wi-Fi. If it disconnects, rejoin it and reopen the local portal.</span></p><a class="button primary" href="/"><span data-i18n>Open dashboard</span> <svg class="icon"><use href="#i-arrow"/></svg></a></section></div><script>try{sessionStorage.setItem('bridgePanel','guide');sessionStorage.setItem('bridgeGuideStep','{{CONFIGURED}}'==='1'?'3':'0')}catch(_){}</script>)UI";

inline constexpr char kMessageBody[] = R"UI(<div class="auth-shell"><section class="auth-story">{{BRAND}}<div class="eyebrow" style="margin-top:55px"><span data-i18n>Action needed</span></div><h1><span data-i18n>{{MESSAGE_TITLE}}</span></h1><p><span data-i18n>{{MESSAGE_TEXT}}</span></p></section><section class="card auth-card"><div class="icon-bubble"><svg class="icon"><use href="#i-compass"/></svg></div><h2><span data-i18n>Let's try again</span></h2><p><span data-i18n>Return to the local portal, review the details, and submit once more.</span></p><a class="button primary" href="/"><span data-i18n>Return to portal</span> <svg class="icon"><use href="#i-arrow"/></svg></a></section></div>)UI";

inline constexpr char kDashboardBody[] = R"UI(<div class="app-shell" data-configured="{{CONFIGURED}}"><aside class="sidebar">{{BRAND}}<nav class="nav" aria-label="Main menu" data-i18n-attr="aria-label"><button type="button" data-panel-button="overview"><svg class="icon"><use href="#i-grid"/></svg> <span data-i18n>Overview</span></button><button type="button" data-panel-button="setup"><svg class="icon"><use href="#i-sliders"/></svg> <span id="setup-nav-label">Setup</span></button><button type="button" data-panel-button="guide"><svg class="icon"><use href="#i-compass"/></svg> <span data-i18n>Guide</span></button><button type="button" data-panel-button="monitor"><svg class="icon"><use href="#i-pulse"/></svg> <span data-i18n>Monitor</span></button><button type="button" data-panel-button="insights"><svg class="icon"><use href="#i-trend"/></svg> <span data-i18n>Insights</span></button><button type="button" data-panel-button="notifications"><svg class="icon"><use href="#i-bell"/></svg> <span data-i18n>Alerts</span></button></nav><div class="sidebar-foot"><span data-i18n>LOCAL MODE</span><br><span data-i18n>Orion data → NMEA 2000</span><br><span data-i18n>Local notifications · No charger control</span></div></aside><div class="content"><header class="topbar"><div><div class="eyebrow"><span data-i18n>Bridge control</span></div><p>Orion · NMEA 2000</p></div><div class="button-row"><span class="pill warn" id="connection"><span data-i18n>Connecting…</span></span><form method="post" action="/logout"><input type="hidden" name="csrf" value="{{CSRF}}"><button type="submit" class="button ghost" aria-label="Sign out" title="Sign out" data-i18n-attr="aria-label title"><svg class="icon"><use href="#i-exit"/></svg></button></form></div></header><div class="notice session-notice" id="session-notice" hidden><span data-i18n>Your session has expired.</span> <a href="/"><span data-i18n>Sign in again</span></a> <span data-i18n>to resume live data.</span></div><div id="notification-banner" class="notice notification-banner" aria-live="polite" hidden><span id="notification-banner-text"></span><button type="button" class="button ghost" data-show="notifications"><span data-i18n>View notifications</span></button></div><main>
<section id="panel-overview" class="panel" hidden><div class="card hero"><div class="eyebrow"><span data-i18n>Live telemetry</span></div><h1><span data-i18n>Power, in focus.</span></h1><p><span data-i18n>Real-time charger input and output values translated to NMEA 2000. Values appear only when a fresh Orion advertisement has been received.</span></p><div class="button-row hero-actions"><button type="button" class="button primary" id="setup-cta" data-show="setup"><svg class="icon"><use href="#i-sliders"/></svg> <span data-i18n>Configure Orion</span></button><button type="button" class="button ghost" data-show="monitor"><svg class="icon"><use href="#i-pulse"/></svg> <span data-i18n>View messages</span></button></div></div><div class="section-heading"><h2><span data-i18n>Charger channels</span></h2><small id="last-update"><span data-i18n>Waiting for data</span></small></div><div class="channel-grid"><section class="card channel-card" aria-labelledby="in-heading"><div class="eyebrow"><span data-i18n>Input · Charger supply</span></div><h3 id="in-heading"><span id="input-alias-label">{{IN_ALIAS}}</span></h3><div class="channel-reading"><div class="label"><span data-i18n>Voltage</span></div><div class="value"><span id="in-v">—</span> <span class="unit">V</span></div></div><div class="channel-reading"><div class="label"><span data-i18n>Current</span></div><div class="value"><span id="in-i">—</span> <span class="unit">A</span></div></div><div class="channel-reading"><div class="label"><span data-i18n>Power (calculated)</span></div><div class="value"><span id="overview-in-w">—</span> <span class="unit">W</span></div></div></section><section class="card channel-card" aria-labelledby="out-heading"><div class="eyebrow"><span data-i18n>Output · Battery charging</span></div><h3 id="out-heading"><span id="output-alias-label">{{OUT_ALIAS}}</span></h3><div class="channel-reading"><div class="label"><span data-i18n>Voltage</span></div><div class="value"><span id="out-v">—</span> <span class="unit">V</span></div></div><div class="channel-reading"><div class="label"><span data-i18n>Current</span></div><div class="value"><span id="out-i">—</span> <span class="unit">A</span></div></div><div class="channel-reading"><div class="label"><span data-i18n>Power (calculated)</span></div><div class="value"><span id="overview-out-w">—</span> <span class="unit">W</span></div></div></section></div><div class="section-heading"><h2><span data-i18n>Bridge health</span></h2><button type="button" class="button ghost" id="refresh"><svg class="icon"><use href="#i-refresh"/></svg> <span data-i18n>Refresh</span></button></div><div class="status-grid health-grid"><div class="card status-card"><small><span data-i18n>Orion status</span></small><strong id="orion-status"><span data-i18n>Waiting</span></strong></div><div class="card status-card"><small><span data-i18n>NMEA status</span></small><strong id="nmea-status">—</strong></div><div class="card status-card"><small><span data-i18n>BLE frames accepted</span></small><strong id="rx-count">0</strong></div><div class="card status-card"><small><span data-i18n>NMEA submissions accepted</span></small><strong id="tx-count">0</strong></div></div><div class="status-legend"><span class="signal" data-severity="ok"><span data-i18n>OK</span></span><span class="signal" data-severity="warn"><span data-i18n>Warning</span></span><span class="signal" data-severity="error"><span data-i18n>Error</span></span></div><p class="footnote"><span data-i18n>The input supplies the Orion; the output charges the connected battery. Currents show only the Orion share, not all charging and consumption at each battery.</span></p></section>
<section id="panel-setup" class="panel" hidden><div class="section-heading"><div><div class="eyebrow"><span data-i18n>Configuration</span></div><h1 id="setup-title">Connect your Orion.</h1><p><span data-i18n>Manage battery names, Orion connection details and NMEA battery instances.</span></p></div></div><div class="card form-card alias-card"><h2><span data-i18n>Battery names</span></h2><p><span data-i18n>Choose a name for each side to identify it in the overview.</span></p><form method="post" action="/aliases" id="aliases-form"><input type="hidden" name="csrf" value="{{CSRF}}"><div class="form-grid"><label class="field"><span data-i18n>Input alias</span><input id="input-alias" name="input_alias" value="{{IN_ALIAS}}" aria-describedby="alias-help input-alias-feedback" autocomplete="off" required><span id="input-alias-feedback" class="field-feedback" aria-live="polite" hidden></span></label><label class="field"><span data-i18n>Output alias</span><input id="output-alias" name="output_alias" value="{{OUT_ALIAS}}" aria-describedby="alias-help output-alias-feedback" autocomplete="off" required><span id="output-alias-feedback" class="field-feedback" aria-live="polite" hidden></span></label></div><p id="alias-help" class="hint"><span data-i18n>Use 1–32 characters and different names for input and output.</span></p><div class="form-actions"><button type="submit" class="button primary" id="aliases-save"><svg class="icon"><use href="#i-check"/></svg> <span data-i18n>Save names</span></button></div><p class="hint"><span data-i18n>Names are saved immediately; the Orion connection stays active.</span></p></form></div><div class="card form-card"><h2>Orion</h2><p><span data-i18n>Find these values in VictronConnect. Your Bluetooth PIN remains on the phone and is never entered here.</span></p><form method="post" action="/config" id="orion-form"><input type="hidden" name="csrf" value="{{CSRF}}"><div class="form-grid"><label class="field"><span data-i18n>Orion Bluetooth MAC</span><input id="orion-mac" name="mac" aria-describedby="mac-feedback" autocapitalize="none" autocorrect="off" spellcheck="false" value="{{MAC}}" placeholder="aa:bb:cc:dd:ee:ff" pattern="([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}" autocomplete="off" required><span class="field-help"><span data-i18n>Enter or paste 12 hexadecimal characters. Colons are added automatically.</span></span><span id="mac-feedback" class="field-feedback" aria-live="polite" hidden></span></label><label class="field"><span data-i18n>Instant Readout encryption key</span><input id="orion-key" name="key" type="password" data-key-present="{{CONFIGURED}}" aria-describedby="key-feedback key-help" autocapitalize="none" autocorrect="off" spellcheck="false" placeholder="32 hexadecimal characters" pattern="[0-9A-Fa-f]{32}" minlength="32" autocomplete="off" required><span id="key-feedback" class="field-feedback" aria-live="polite" hidden></span><span class="field-help" id="key-help"><span data-i18n>Leave this field empty to keep the stored key for this Orion. Enter all 32 hexadecimal characters to replace it. A different Orion MAC requires its own key.</span></span></label><label class="field"><span data-i18n>NMEA output instance</span><input name="out" type="number" aria-describedby="output-feedback" min="0" max="252" value="{{OUT_INSTANCE}}" required><span class="field-help"><span data-i18n>Battery instance used for charger output values.</span></span><span id="output-feedback" class="field-feedback" aria-live="polite" hidden></span></label><label class="field"><span data-i18n>NMEA input instance</span><input name="in" type="number" aria-describedby="input-feedback" min="0" max="252" value="{{IN_INSTANCE}}" required><span class="field-help"><span data-i18n>Use a different number for the charger input.</span></span><span id="input-feedback" class="field-feedback" aria-live="polite" hidden></span></label></div><div class="form-actions"><button type="submit" class="button primary" id="orion-save"><svg class="icon"><use href="#i-check"/></svg> <span data-i18n>Save and restart</span></button><button type="button" class="button ghost" data-show="guide"><svg class="icon"><use href="#i-compass"/></svg> <span data-i18n>Open setup guide</span></button></div></form><hr class="divider"><h3><span data-i18n>Remove a device</span></h3><p><span data-i18n>Erase the saved Orion MAC and readout key if you replace the charger.</span></p><form method="post" action="/forget" onsubmit="return confirm(bridgeI18n.t('Forget the saved Orion identity and key?'))"><input type="hidden" name="csrf" value="{{CSRF}}"><button type="submit" class="button danger"><svg class="icon"><use href="#i-trash"/></svg> <span data-i18n>Forget Orion</span></button></form></div><div class="card form-card password-card" id="password-card"><div class="eyebrow"><span data-i18n>Administrator access</span></div><h2><span data-i18n>Change password</span></h2><p><span data-i18n>Choose a personal password for the web interface. You will sign in again after saving.</span></p><div class="notice"><span data-i18n>If you recovered access using the public recovery password, replace it now.</span></div><form id="password-form" method="post" action="/password"><input type="hidden" name="csrf" value="{{CSRF}}"><label class="field"><span data-i18n>Current password</span><input id="current-password" name="current_password" type="password" autocomplete="current-password" aria-describedby="current-password-feedback" required><span id="current-password-feedback" class="field-feedback" aria-live="polite" hidden></span></label><div class="form-grid"><label class="field"><span data-i18n>New password</span><input id="new-password" name="new_password" type="password" autocomplete="new-password" aria-describedby="password-help new-password-feedback" required><span id="new-password-feedback" class="field-feedback" aria-live="polite" hidden></span></label><label class="field"><span data-i18n>Repeat new password</span><input id="confirm-password" name="confirm_password" type="password" autocomplete="new-password" aria-describedby="confirm-password-feedback" required><span id="confirm-password-feedback" class="field-feedback" aria-live="polite" hidden></span></label></div><p id="password-help" class="hint"><span data-i18n>Use 12–128 bytes of text. Most letters and numbers use one byte; accents and emoji use more. Spaces are kept exactly as entered.</span></p><div class="form-actions"><button class="button primary" id="password-save" type="submit"><svg class="icon"><use href="#i-lock"/></svg><span data-i18n>Change password</span></button></div><p id="password-status" class="hint account-status" role="status" aria-live="polite" hidden></p></form></div><div class="card form-card ota-card" id="firmware-card"><div class="eyebrow"><span data-i18n>Device maintenance</span></div><h2><span data-i18n>Firmware update</span></h2><p><span data-i18n>Upload an application firmware .bin file already saved on your phone. No internet connection is needed.</span></p><div class="firmware-meta"><div><small><span data-i18n>Installed version</span></small><strong id="firmware-version">—</strong></div><div><small><span data-i18n>Device target</span></small><strong id="firmware-target">—</strong></div></div><div class="notice blue"><span data-i18n>The device checks the product, processor, image structure, checksum and SHA-256 before activation. Use firmware from a trusted source; these checks do not verify the publisher.</span></div><p class="hint"><span data-i18n>Keep the device powered and your phone connected to its Wi-Fi. Live data pauses during the update. The device restarts after successful installation.</span></p><label class="field"><span data-i18n>Firmware file (.bin)</span><input id="firmware-file" type="file" accept=".bin,application/octet-stream" aria-describedby="firmware-limit firmware-selected" disabled><span class="field-help" id="firmware-limit">—</span></label><p id="firmware-selected" class="hint"><span data-i18n>No firmware file selected.</span></p><div id="firmware-progress-wrap" hidden><label for="firmware-progress" id="firmware-percent"></label><progress id="firmware-progress" max="100" value="0"></progress></div><p id="firmware-status" class="firmware-status" role="status" aria-live="polite"><span data-i18n>Reading firmware information…</span></p><div class="form-actions"><button type="button" class="button primary" id="firmware-install" disabled><svg class="icon"><use href="#i-arrow"/></svg><span data-i18n>Upload and install</span></button><button type="button" class="button ghost" id="firmware-cancel" hidden><span data-i18n>Cancel upload</span></button><button type="button" class="button ghost" id="firmware-retry" hidden><span data-i18n>Read device information again</span></button><a class="button ghost" id="firmware-reopen" href="/" hidden><span data-i18n>Reopen portal</span></a></div></div></section>
<section id="panel-guide" class="panel" hidden><div class="section-heading"><div><div class="eyebrow"><span data-i18n>Guided installation</span></div><h1><span data-i18n>From first boot to Garmin.</span></h1><p><span data-i18n>Follow these steps in order. You can return to this guide at any time.</span></p></div></div><div class="card guide-card"><div class="guide-progress"><span id="step-label"><span data-i18n>Step 1 of 4</span></span><span id="step-name"><span data-i18n>Access ready</span></span></div><div class="progress-track"><div class="progress-fill" id="progress-fill"></div></div><article class="guide-step" data-guide-step="0"><div class="step-no">01</div><h3><span data-i18n>Your local access is ready</span></h3><p><span data-i18n>You are already connected and signed in. Continue with the Orion details in the next step.</span></p><div class="notice blue"><span data-i18n>For first connection instructions before joining the dongle, open or save docs/erstverbindung.md from the project README.</span></div><details class="access-note"><summary><span data-i18n>Reconnect later</span></summary><p><span data-i18n>Hold BOOT for two seconds to reopen the service Wi-Fi if it has timed out.</span></p><p><code>OrionBridge-…</code> · <code>https://192.168.4.1/</code></p><p><span data-i18n>For the Wi-Fi password, open the USB serial monitor at 115200 baud and hold BOOT for two seconds after startup. Read the</span> <code>Service AP password</code> <span data-i18n>line.</span></p></details></article><article class="guide-step" data-guide-step="1" hidden><div class="step-no">02</div><h3><span data-i18n>Collect Orion readout details</span></h3><p><span data-i18n>On your phone, connect to the Orion XS in VictronConnect using its Bluetooth PIN. Enable Instant Readout and note the charger's Bluetooth MAC and its 32-character Instant Readout encryption key from device information.</span></p><div class="notice blue"><span data-i18n>Keep the PIN in VictronConnect. The dongle needs the readout key and MAC, not the PIN. Do not store them in the project source.</span></div></article><article class="guide-step" data-guide-step="2" hidden><div class="step-no">03</div><h3><span data-i18n>Map the two NMEA channels</span></h3><p><span data-i18n>Open Setup, enter the Orion MAC and readout key, then choose different battery instance numbers for charger output and input. Both numbers must be between 0 and 252. The defaults are output 0 and input 1; change them if those numbers already represent another battery on your NMEA network.</span></p><p><span data-i18n>Save and let the dongle restart. Rejoin its service Wi-Fi if needed.</span></p><button type="button" class="button primary" data-show="setup"><svg class="icon"><use href="#i-arrow"/></svg> <span data-i18n>Go to setup</span></button></article><article class="guide-step" data-guide-step="3" hidden><div class="step-no">04</div><h3><span data-i18n>Verify before sailing</span></h3><p><span data-i18n>Compare Overview values with VictronConnect. Monitor shows BLE reception, stale data, and NMEA transmission results. On the Garmin GPSMAP 723xsv, select the intended battery source or data instances.</span></p><ul><li><span data-i18n>A bare ESP32-C3 can test the web interface and Bluetooth reception, but needs a CAN transceiver and protected NMEA 2000 connection before Garmin can receive messages.</span></li><li><span data-i18n>This bridge forwards Orion telemetry and can warn about configured limits. It does not estimate battery state of charge or control the charger.</span></li></ul><button type="button" class="button ghost" data-show="monitor"><svg class="icon"><use href="#i-pulse"/></svg> <span data-i18n>Open live monitor</span></button></article><div class="guide-controls"><button type="button" class="button ghost" id="step-prev"><span data-i18n>Previous</span></button><button type="button" class="button primary" id="step-next"><span data-i18n>Next step</span> <svg class="icon"><use href="#i-arrow"/></svg></button></div></div></section>
<section id="panel-monitor" class="panel" hidden><div class="section-heading"><div><div class="eyebrow"><span data-i18n>Diagnostics</span></div><h1><span data-i18n>Parameter dashboard.</span></h1><p><span data-i18n>All decoded Orion parameters and the latest NMEA telemetry submissions, updated automatically.</span></p></div></div><div class="parameter-grid"><section class="card parameter-card"><h2><span data-i18n>Orion / Bluetooth</span></h2><table class="parameters"><tbody><tr><th scope="row"><span data-i18n>Orion status</span></th><td><span id="monitor-orion-status">—</span></td></tr><tr><th scope="row"><span data-i18n>BLE frames accepted</span></th><td><span id="monitor-rx">—</span></td></tr><tr><th scope="row"><span data-i18n>Orion errors</span></th><td><span id="orion-errors">—</span></td></tr><tr><th scope="row"><span data-i18n>Rejected records</span></th><td><span id="rejected">—</span></td></tr><tr><th scope="row"><span data-i18n>Queue drops</span></th><td><span id="dropped">—</span></td></tr><tr><th scope="row"><span data-i18n>Startup failures</span></th><td><span id="startup-failed">—</span></td></tr><tr><th scope="row"><span data-i18n>Duplicate frames (ignored)</span></th><td><span id="duplicates">—</span></td></tr></tbody></table></section><section class="card parameter-card"><h2><span data-i18n>NMEA 2000</span></h2><table class="parameters"><tbody><tr><th scope="row"><span data-i18n>NMEA submissions accepted</span></th><td><span id="monitor-tx">—</span></td></tr><tr><th scope="row"><span data-i18n>NMEA errors</span></th><td><span id="nmea-errors">—</span></td></tr></tbody></table></section></div><p class="hint"><span data-i18n>Counters start at boot. Orion errors include rejected records, queue drops and startup failures; duplicate advertisements are counted separately. NMEA errors count rejected send requests, not confirmations from Garmin.</span></p><div class="parameter-grid"><section class="card parameter-card"><h2><span data-i18n>Orion received parameters</span></h2><table class="parameters"><tbody><tr><th scope="row"><span data-i18n>Output voltage</span></th><td><span id="monitor-out-v">—</span> V</td></tr><tr><th scope="row"><span data-i18n>Output current</span></th><td><span id="monitor-out-i">—</span> A</td></tr><tr><th scope="row"><span data-i18n>Output power (calculated)</span></th><td><span id="out-w">—</span> W</td></tr><tr><th scope="row"><span data-i18n>Input voltage</span></th><td><span id="monitor-in-v">—</span> V</td></tr><tr><th scope="row"><span data-i18n>Input current</span></th><td><span id="monitor-in-i">—</span> A</td></tr><tr><th scope="row"><span data-i18n>Input power (calculated)</span></th><td><span id="in-w">—</span> W</td></tr><tr><th scope="row"><span data-i18n>Charger state (code)</span></th><td><span id="charger-state">—</span></td></tr><tr><th scope="row"><span data-i18n>Charger error (code)</span></th><td><span id="charger-error">—</span></td></tr><tr><th scope="row"><span data-i18n>Off reason (bitmask)</span></th><td><span id="off-reason">—</span></td></tr><tr><th scope="row"><span data-i18n>Frame counter</span></th><td><span id="frame-counter">—</span></td></tr><tr><th scope="row"><span data-i18n>Signal strength</span></th><td><span id="rssi">—</span> dBm</td></tr><tr><th scope="row"><span data-i18n>BLE age</span></th><td><span id="ble-age">—</span> ms</td></tr><tr><th scope="row"><span data-i18n>Data freshness</span></th><td><span id="freshness">—</span></td></tr></tbody></table></section><section class="card parameter-card"><h2><span data-i18n>Resolution and availability</span></h2><p><span data-i18n>Electrical values use three decimal places. Orion reports voltage in 0.01 V steps and current in 0.1 A steps; trailing zeros do not add precision. Power is calculated from voltage and current.</span></p><p><span data-i18n>Codes, counters and instances are integers. Unavailable or stale Orion measurements appear as a dash.</span></p><p><span data-i18n>NMEA cards retain the last submission with its age and encoded values. An accepted request does not confirm delivery on the CAN bus. Network management messages are outside this telemetry view.</span></p></section></div><div class="section-heading"><h2><span data-i18n>NMEA telemetry parameters</span></h2></div><div id="nmea-parameters" class="parameter-grid"></div><div class="card monitor-card"><h2><span data-i18n>Recent messages</span></h2><p><span data-i18n>New events appear automatically while this page is open.</span></p><div class="log" id="events" role="log" aria-live="polite"><span data-i18n>Waiting for device events…</span></div></div><p class="footnote"><span data-i18n>Events use UTC when a trusted network clock is available; otherwise they show device uptime. Earlier events from this start receive estimated calendar times once the clock is known.</span></p></section>
<section id="panel-insights" class="panel" hidden><div class="section-heading"><div><div class="eyebrow"><span data-i18n>Observation</span></div><h1><span data-i18n>Voltage and energy.</span></h1><p><span data-i18n>Follow both Orion connections over time.</span></p></div></div><p id="insights-status" class="pill"></p><div class="parameter-grid"><article class="card insight-card"><div class="eyebrow"><span data-i18n>Orion input</span></div><h2>{{IN_ALIAS}}</h2><p id="insights-input-trend"></p><svg id="insights-input-chart" class="voltage-chart" viewBox="0 0 500 120" role="img" aria-label="Voltage history" data-i18n-attr="aria-label"></svg><p class="hint"><span data-i18n>Recent voltage observations; gaps remain visible.</span></p><dl class="insight-values"><div><dt><span data-i18n>Minimum voltage</span></dt><dd id="insights-input-min">—</dd></div><div><dt><span data-i18n>Maximum voltage</span></dt><dd id="insights-input-max">—</dd></div><div><dt><span data-i18n>Observed Orion charge</span></dt><dd id="insights-input-ah">—</dd></div><div><dt><span data-i18n>Observed Orion energy</span></dt><dd id="insights-input-wh">—</dd></div><div class="wide"><dt id="insights-input-low-label"></dt><dd id="insights-input-low-time">—</dd></div></dl><p id="insights-input-coverage" class="hint"></p></article><article class="card insight-card"><div class="eyebrow"><span data-i18n>Orion output</span></div><h2>{{OUT_ALIAS}}</h2><p id="insights-output-trend"></p><svg id="insights-output-chart" class="voltage-chart" viewBox="0 0 500 120" role="img" aria-label="Voltage history" data-i18n-attr="aria-label"></svg><p class="hint"><span data-i18n>Recent voltage observations; gaps remain visible.</span></p><dl class="insight-values"><div><dt><span data-i18n>Minimum voltage</span></dt><dd id="insights-output-min">—</dd></div><div><dt><span data-i18n>Maximum voltage</span></dt><dd id="insights-output-max">—</dd></div><div><dt><span data-i18n>Observed Orion charge</span></dt><dd id="insights-output-ah">—</dd></div><div><dt><span data-i18n>Observed Orion energy</span></dt><dd id="insights-output-wh">—</dd></div><div class="wide"><dt id="insights-output-low-label"></dt><dd id="insights-output-low-time">—</dd></div></dl><p id="insights-output-coverage" class="hint"></p></article></div><div class="notice blue"><span data-i18n>Values are measured at the Orion input and output. Charge and energy totals cover only the observed Orion flow, not all battery use. Missing data is excluded. Observations restart when the bridge restarts.</span></div><p id="insights-time" class="hint"></p></section><section id="panel-notifications" class="panel" hidden><div class="section-heading"><div><div class="eyebrow"><span data-i18n>Stay informed</span></div><h1><span data-i18n>Notifications.</span></h1><p><span data-i18n>Set voltage limits separately for each Orion connection.</span></p></div></div><p id="notifications-state" class="pill"></p><div id="notification-alerts" aria-live="polite"></div><form id="notifications-form" method="post" action="/notifications"><input type="hidden" name="csrf" value="{{CSRF}}"><section class="card form-card"><label class="confirmation"><input type="checkbox" name="enabled" value="1"><span data-i18n>Enable notifications</span></label><p><span data-i18n>Warnings stay active during charging. Acknowledging a warning does not clear its cause.</span></p><label class="field"><span data-i18n>Repeat unacknowledged warnings every (min)</span><input type="number" name="repeat_minutes" value="0" min="0" max="1440" step="1" required inputmode="decimal"></label><p class="hint"><span data-i18n>Use 0 to turn off reminders.</span></p></section><div class="parameter-grid"><fieldset class="card notification-bank"><legend><span data-i18n>Orion input</span> · {{IN_ALIAS}}</legend><label class="confirmation"><input type="checkbox" name="input_low_enabled" value="1"><span data-i18n>Low voltage warning</span></label><div class="form-grid"><label class="field"><span data-i18n>Warn below (V)</span><input type="number" name="input_low_v" value="12" min="4" max="65" step=".01" required inputmode="decimal"></label><label class="field"><span data-i18n>Clear above (V)</span><input type="number" name="input_low_clear_v" value="12.3" min="4" max="65" step=".01" required inputmode="decimal"></label></div><label class="confirmation"><input type="checkbox" name="input_high_enabled" value="1"><span data-i18n>High voltage warning</span></label><div class="form-grid"><label class="field"><span data-i18n>Warn above (V)</span><input type="number" name="input_high_v" value="15" min="4" max="65" step=".01" required inputmode="decimal"></label><label class="field"><span data-i18n>Clear below (V)</span><input type="number" name="input_high_clear_v" value="14.7" min="4" max="65" step=".01" required inputmode="decimal"></label><label class="field"><span data-i18n>Confirm warning for (s)</span><input type="number" name="input_delay_s" value="10" min="1" max="600" step="1" required inputmode="decimal"></label><label class="field"><span data-i18n>Confirm clear for (s)</span><input type="number" name="input_clear_s" value="30" min="1" max="600" step="1" required inputmode="decimal"></label></div></fieldset><fieldset class="card notification-bank"><legend><span data-i18n>Orion output</span> · {{OUT_ALIAS}}</legend><label class="confirmation"><input type="checkbox" name="output_low_enabled" value="1"><span data-i18n>Low voltage warning</span></label><div class="form-grid"><label class="field"><span data-i18n>Warn below (V)</span><input type="number" name="output_low_v" value="12" min="4" max="65" step=".01" required inputmode="decimal"></label><label class="field"><span data-i18n>Clear above (V)</span><input type="number" name="output_low_clear_v" value="12.3" min="4" max="65" step=".01" required inputmode="decimal"></label></div><label class="confirmation"><input type="checkbox" name="output_high_enabled" value="1"><span data-i18n>High voltage warning</span></label><div class="form-grid"><label class="field"><span data-i18n>Warn above (V)</span><input type="number" name="output_high_v" value="15" min="4" max="65" step=".01" required inputmode="decimal"></label><label class="field"><span data-i18n>Clear below (V)</span><input type="number" name="output_high_clear_v" value="14.7" min="4" max="65" step=".01" required inputmode="decimal"></label><label class="field"><span data-i18n>Confirm warning for (s)</span><input type="number" name="output_delay_s" value="10" min="1" max="600" step="1" required inputmode="decimal"></label><label class="field"><span data-i18n>Confirm clear for (s)</span><input type="number" name="output_clear_s" value="30" min="1" max="600" step="1" required inputmode="decimal"></label></div></fieldset></div><section class="card form-card"><label class="confirmation"><input type="checkbox" name="data_loss_enabled" value="1"><span data-i18n>Notify when Orion data is missing</span></label><label class="field"><span data-i18n>Confirm missing data for (s)</span><input type="number" name="data_loss_delay_s" value="30" min="10" max="3600" step="1" required inputmode="decimal"></label><label class="confirmation"><input type="checkbox" name="charger_error_enabled" value="1"><span data-i18n>Notify about Orion charger errors</span></label><label class="confirmation"><input type="checkbox" name="nmea_enabled" value="1"><span data-i18n>Request Garmin notifications</span></label><p id="nmea-alert-status" class="notice"></p><div class="form-actions"><button class="button primary" id="notifications-save" type="submit" disabled><span data-i18n>Save notifications</span></button><span id="notifications-form-status" class="hint" role="status"></span></div></section></form></section>
</main><div class="footnote"><span data-i18n>Battery Sentinel · Orion Bridge · Local service interface</span></div></div></div><script>
const root=document.querySelector('.app-shell');
const configured=root.dataset.configured==='1';
const panels=['overview','setup','guide','monitor','insights','notifications'];
const tr=bridgeI18n.t;
let guideStep=0,last=0,timer=0,busy=false,expired=false;
let liveController=null,livePending=null,liveSettled=null,livePaused=false;
const liveSuspended=()=>livePaused||document.hidden||window.bridgeOtaBusy||window.bridgeAccountSaving||window.bridgeFirmwarePicking||window.bridgeFirmwareLoading;
let latest=null,connectionState='connecting',eventBuffer=[],lastBootId=null;
// Storage is optional; private/restricted browsers must still show the portal.
function remember(key,value){try{sessionStorage.setItem(key,value)}catch(_){}}
function recall(key){try{return sessionStorage.getItem(key)}catch(_){return null}}
function showPanel(name){
  if(window.bridgeOtaBusy||window.bridgeAccountSaving)return;
  if(!panels.includes(name))name='overview';
  for(const p of panels){
    document.getElementById('panel-'+p).hidden=p!==name;
    document.querySelector('[data-panel-button="'+p+'"]').setAttribute('aria-current',p===name?'page':'false');
  }
  remember('bridgePanel',name);
  window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
}
document.querySelectorAll('[data-panel-button],[data-show]').forEach(b=>b.addEventListener('click',()=>showPanel(b.dataset.panelButton||b.dataset.show)));
const stepNames=['Access ready','Orion details','NMEA mapping','Verification'];
function showStep(n){
  guideStep=Number.isFinite(n)?Math.max(0,Math.min(3,Math.trunc(n))):0;
  remember('bridgeGuideStep',String(guideStep));
  document.querySelectorAll('[data-guide-step]').forEach((s,i)=>s.hidden=i!==guideStep);
  document.getElementById('step-label').textContent=tr('Step {step} of 4',{step:guideStep+1});
  document.getElementById('step-name').textContent=tr(stepNames[guideStep]);
  document.getElementById('progress-fill').style.width=((guideStep+1)*25)+'%';
  document.getElementById('step-prev').disabled=guideStep===0;
  document.getElementById('step-next').textContent=tr(guideStep===3?'Open overview':'Next step');
}
document.getElementById('step-prev').onclick=()=>showStep(guideStep-1);
document.getElementById('step-next').onclick=()=>guideStep===3?showPanel('overview'):showStep(guideStep+1);
showStep(Number(recall('bridgeGuideStep')));
showPanel((window.location?.hash||'').slice(1)||recall('bridgePanel')||(configured?'overview':'guide'));
const orionForm=document.getElementById('orion-form');
const formController=bridgeForm.init(orionForm,tr);
const aliasController=bridgeForm.initAliases(document.getElementById('aliases-form'),tr);
const passwordController=bridgeForm.initPassword(document.getElementById('password-form'),tr);
bridgeInsights.init();
function renderConfiguration(){
  document.getElementById('setup-cta').hidden=configured;
  document.getElementById('setup-nav-label').textContent=tr(configured?'Settings':'Setup');
  document.getElementById('setup-title').textContent=tr(configured?'Orion settings.':'Connect your Orion.');
}
renderConfiguration();
function put(id,v,suffix=''){document.getElementById(id).textContent=v==null?'—':String(v)+suffix}
function metric(v){return v==null?'—':Number(v).toLocaleString(bridgeI18n.language==='de'?'de-DE':'en-US',{minimumFractionDigits:3,maximumFractionDigits:3,useGrouping:false})}
const liveIds=['overview-in-w','overview-out-w','out-v','out-i','in-v','in-i','monitor-out-v','monitor-out-i','monitor-in-v','monitor-in-i','out-w','in-w','rssi','charger-state','charger-error','off-reason','ble-age','frame-counter','freshness','rx-count','tx-count','monitor-rx','monitor-tx','orion-errors','nmea-errors','rejected','dropped','duplicates','startup-failed'];
function clearLiveValues(){for(const id of liveIds)put(id,null);put('orion-status',tr('Unavailable'));put('monitor-orion-status',tr('Unavailable'));put('nmea-status',tr('Unavailable'));for(const id of ['orion-status','monitor-orion-status','nmea-status','orion-errors','nmea-errors','rejected','dropped','startup-failed','charger-error','off-reason','freshness'])signal(id,'neutral');renderNmea([])}
const receiverErrors=['Encryption key mismatch','Unsupported advertisement','Truncated or oversized record','AES decode failed','Record decode failed','Implausible decoded values','Invalid BLE settings','BLE queue allocation failed','BLE scan failed'];
function signal(id,severity){const node=document.getElementById(id);node.dataset.severity=severity;node.classList.add('signal');node.setAttribute('aria-label',tr({ok:'OK',warn:'Warning',error:'Error',neutral:'Unavailable'}[severity])+': '+node.textContent)}
function orionHealth(x){
  if(receiverErrors.includes(x.status))return {level:'error',text:x.status};
  if(x.fresh&&x.error!=null&&x.error!==255&&x.error!==0)return {level:'error',text:'Charger reports an error'};
  if(x.status!=='Receiving'||!x.fresh)return {level:'warn',text:x.status||'Waiting for data'};
  if(x.offReason!=null&&x.offReason!==0)return {level:'warn',text:'Charger switched off'};
  if([x.outV,x.outI,x.inV,x.inI,x.error,x.offReason,x.state].some(v=>v==null)||x.error===255||x.state===255)return {level:'warn',text:'Some Orion values are unavailable'};
  if(x.orionErrors>0)return {level:'warn',text:'Receiving; earlier errors recorded'};
  return {level:'ok',text:'Receiving'};
}
function nmeaHealth(x){
  const eligible=x.fresh&&x.error===0&&[3,4,5].includes(x.state);
  const records=(x.nmea||[]).filter(r=>r.pgn!==127507||eligible);
  const overdue=r=>r.age!=null&&r.age>(r.pgn===127506?15000:3500);
  if(records.some(r=>r.accepted===false&&!overdue(r)))return {level:'error',text:'NMEA submission failed'};
  if(records.length<(eligible?5:4)||records.some(r=>r.accepted==null))return {level:'warn',text:'Waiting for NMEA submissions'};
  if(records.some(overdue))return {level:'warn',text:'NMEA update overdue'};
  if(x.nmeaErrors>0)return {level:'warn',text:'Submissions accepted; earlier errors recorded'};
  return {level:'ok',text:'NMEA submissions accepted'};
}
function renderHealth(x){
  const orion=orionHealth(x),nmea=nmeaHealth(x);
  for(const id of ['orion-status','monitor-orion-status']){put(id,tr(orion.text));signal(id,orion.level)}
  put('nmea-status',tr(nmea.text));signal('nmea-status',nmea.level);
  for(const [id,key] of [['orion-errors','orionErrors'],['nmea-errors','nmeaErrors'],['rejected','rejected'],['dropped','dropped'],['startup-failed','orionStartupFailed']])signal(id,x[key]==null?'neutral':x[key]>0?'warn':'ok');
  signal('charger-error',x.error==null||x.error===255?'warn':x.error===0?'ok':'error');
  signal('off-reason',x.offReason==null?'neutral':x.offReason===0?'ok':'warn');
  signal('freshness',x.fresh?'ok':'warn');
  return orion.level==='error'||nmea.level==='error'?'error':orion.level==='warn'||nmea.level==='warn'?'warn':'ok';
}
function eventSeverity(event){
  if(event.type==='ALERT')return /: (activated|reminder)$/.test(event.detail)?'warn':/: (cleared|acknowledged)$/.test(event.detail)?'ok':'neutral';
  if(event.type==='TIME')return /conflict|unavailable/.test(event.detail)?'warn':'neutral';
  if(receiverErrors.includes(event.detail)||/; failed [1-9]/.test(event.detail)||/failed [1-9]/.test(event.detail))return 'error';
  if(/stale|unavailable|\bNA\b|Waiting for|identity and key required/i.test(event.detail))return 'warn';
  if(/^Orion state /.test(event.detail)||/; (sent|accepted) /.test(event.detail))return 'ok';
  return 'neutral';
}
const nmeaFields={sid:['Sequence ID','',false],voltage:['Voltage','V',true],current:['Current','A',true],temperature:['Temperature','K',true],batteryInstance:['Battery instance','',false],chargeState:['Charge state (code)','',false],chargerMode:['Charger mode (code)','',false],enabled:['Enabled (code)','',false],equalizationPending:['Equalization pending (code)','',false],equalizationTimeRemaining:['Equalization time remaining','s',true],dcType:['DC type (code)','',false],soc:['State of charge','%',true],soh:['State of health','%',true],timeRemaining:['Time remaining','s',true],rippleVoltage:['Ripple voltage','V',true],capacity:['Capacity','C',true]};
function renderNmea(records){
  const container=document.getElementById('nmea-parameters');container.replaceChildren();
  if(!records.length){const p=document.createElement('p');p.textContent=tr('No NMEA submission data available.');container.appendChild(p);return}
  for(const record of records){
    const card=document.createElement('section');card.className='card parameter-card';
    const title=document.createElement('h3');title.textContent='PGN '+record.pgn+' · '+tr('Instance')+' '+record.instance;card.appendChild(title);
    const status=document.createElement('p');status.className='nmea-summary';
    status.dataset.severity=record.accepted==null?'warn':record.accepted?'ok':'error';status.classList.add('signal');
    status.textContent=tr(record.accepted==null?'Not submitted yet':record.accepted?'Last submission accepted':'Last submission failed')+(record.age==null?'':' · '+tr('Age')+' '+record.age+' ms');card.appendChild(status);
    const table=document.createElement('table');table.className='parameters';
    const tbody=document.createElement('tbody');
    for(const [key,value] of Object.entries(record.fields)){
      const [label,unit,decimal]=nmeaFields[key]||[key,'',false];
      const row=document.createElement('tr'),name=document.createElement('th'),cell=document.createElement('td');
      name.scope='row';name.textContent=tr(label);cell.textContent=value==null?tr('Unavailable'):(decimal?metric(value):String(value))+(unit?' '+unit:'');
      row.appendChild(name);row.appendChild(cell);tbody.appendChild(row);
    }
    table.appendChild(tbody);card.appendChild(table);container.appendChild(card);
  }
}
function renderEvents(){
  const log=document.getElementById('events');log.replaceChildren();
  if(!eventBuffer.length)log.textContent=tr('Waiting for device events…');
  for(const event of eventBuffer){
    const line=document.createElement('span');line.className='log-line';line.dataset.severity=eventSeverity(event);
    line.textContent=bridgeInsights.eventTime(event)+'  '+event.type+'  '+bridgeI18n.eventText(event.detail)+'\n';log.appendChild(line);
  }
  log.scrollTop=log.scrollHeight;
}
function renderLive(){
  bridgeInsights.update(connectionState==='online'?latest:null);
  const c=document.getElementById('connection');
  if(connectionState==='online'&&latest){
    const x=latest;
    put('out-v',metric(x.outV));put('out-i',metric(x.outI));put('in-v',metric(x.inV));put('in-i',metric(x.inI));
    put('orion-status',tr(x.status));put('rx-count',x.rx);put('tx-count',x.tx);
    put('overview-out-w',metric(x.outW));put('overview-in-w',metric(x.inW));put('out-w',metric(x.outW));put('in-w',metric(x.inW));put('rssi',x.rssi);put('ble-age',x.age);
    put('charger-state',x.state);put('charger-error',x.error);put('off-reason',x.offReason==null?null:x.offReason+' (0x'+Number(x.offReason).toString(16).toUpperCase().padStart(8,'0')+')');
    for(const [id,key] of [['monitor-out-v','outV'],['monitor-out-i','outI'],['monitor-in-v','inV'],['monitor-in-i','inI']])put(id,metric(x[key]));
    for(const [id,key] of [['monitor-rx','rx'],['monitor-tx','tx'],['orion-errors','orionErrors'],['nmea-errors','nmeaErrors'],['rejected','rejected'],['dropped','dropped'],['duplicates','duplicates'],['startup-failed','orionStartupFailed'],['frame-counter','counter']])put(id,x[key]);
    put('monitor-orion-status',tr(x.status));put('freshness',tr(!x.received?'Waiting for data':x.fresh?'Fresh':'Stale'));
    renderNmea(x.nmea||[]);
    document.getElementById('last-update').textContent=tr('Updated just now');
    const health=renderHealth(x);c.textContent=tr(x.status==='Unconfigured'?'Setup needed':health==='error'?'Bridge error':health==='warn'?'Bridge warning':'Bridge ready');c.className='pill'+(health==='ok'?'':' '+health);c.dataset.severity=health;
  }else if(connectionState==='connecting'){
    c.textContent=tr('Connecting…');c.className='pill warn';c.dataset.severity='warn';
  }else{
    clearLiveValues();
    c.textContent=tr(expired?'Sign-in required':'Connection interrupted');c.className='pill error';c.dataset.severity='error';
    document.getElementById('last-update').textContent=tr(expired?'Sign in to resume':'Waiting to reconnect');
  }
}
async function tick(){
  clearTimeout(timer);
  if(busy||expired||liveSuspended())return;
  busy=true;
  livePending=new Promise(resolve=>{liveSettled=resolve});
  let timeout=0;
  try{
    const controller=liveController=new AbortController();
    timeout=setTimeout(()=>controller.abort(),12000);
    const r=await fetch('/api/live?after='+last,{cache:'no-store',signal:controller.signal});
    if(r.status===401){expired=true;document.getElementById('session-notice').hidden=false;throw Error('expired')}
    if(!r.ok)throw Error('HTTP '+r.status);
    latest=await r.json();connectionState='online';
    if(latest.bootId!=null&&latest.bootId!==lastBootId){if(lastBootId!==null){last=0;eventBuffer=[];latest.events=[]}lastBootId=latest.bootId}
    if(latest.events&&latest.events.length){
      for(const e of latest.events){last=e.seq;eventBuffer.push(e)}
      eventBuffer=eventBuffer.slice(-64);
      renderEvents();
    }
    renderLive();renderEvents();
  }catch(_){
    if(!liveSuspended()){latest=null;connectionState='offline';renderLive()}
  }finally{
    clearTimeout(timeout);busy=false;liveController=null;
    liveSettled();livePending=null;liveSettled=null;
    if(!expired&&!liveSuspended())timer=setTimeout(tick,3000);
  }
}
window.bridgePauseLive=()=>{livePaused=true;clearTimeout(timer);if(liveController)liveController.abort();return livePending||Promise.resolve()};
window.bridgeResumeLive=(delay=0)=>{
  if(expired||document.hidden||window.bridgeOtaBusy||window.bridgeAccountSaving||window.bridgeFirmwarePicking||window.bridgeFirmwareLoading)return;
  livePaused=false;
  const resume=()=>{if(expired||liveSuspended())return;clearTimeout(timer);if(delay>0)timer=setTimeout(tick,delay);else tick()};
  if(livePending)livePending.then(resume);else resume();
};
window.addEventListener('bridge-language-change',()=>{showStep(guideStep);formController.refreshLanguage();aliasController.refreshLanguage();passwordController.refreshLanguage();renderConfiguration();renderLive();renderEvents()});
document.getElementById('refresh').onclick=tick;
document.addEventListener('visibilitychange',()=>{if(document.hidden)window.bridgePauseLive();else window.bridgeResumeLive(500)});
// Wait for the streamed HTML to finish before competing for its TLS slot.
function startDeviceRequests(){bridgeOta.init();tick()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startDeviceRequests,{once:true});else startDeviceRequests();
</script>)UI";

